class DiscountCalculator {
    double apply(String type, double price) {
        if (type.equals("STUDENT"))      return price * 0.9;
        if (type.equals("BLACK_FRIDAY")) return price * 0.5;
        return price;
    }
}

interface DiscountPolicy { double apply(double price); }

class StudentDiscount     implements DiscountPolicy { public double apply(double p) { return p * 0.9; } }
class BlackFridayDiscount implements DiscountPolicy { public double apply(double p) { return p * 0.5; } }
class NoDiscount          implements DiscountPolicy { public double apply(double p) { return p; } }

double checkout(DiscountPolicy policy, double price) {
    return policy.apply(price);
}

