class Validator {
    /** Returns the trimmed name; never null. Rejects blank input. */
    String normalize(String name) {
        if (name.isBlank()) throw new IllegalArgumentException("blank");
        return name.trim();
    }
}

class LenientValidator extends Validator {
    @Override
    String normalize(String name) {
        if (name.isBlank()) return null;
        return name.trim();
    }
}

