interface PaymentGateway { String charge(double amount); }   // never returns null

class StripeGateway implements PaymentGateway {
    public String charge(double amount) { return "receipt-" + amount; }
}

class LegacyGateway implements PaymentGateway {
    public String charge(double amount) { throw new UnsupportedOperationException(); }
}

class OrderService {
    private final PaymentGateway gateway;
    OrderService(PaymentGateway gateway) { this.gateway = gateway; }
    void pay(double amount) { System.out.println(gateway.charge(amount).toUpperCase()); }
}

new OrderService(new LegacyGateway()).pay(10);

